//@ 299
void UIFunction_ToggleMonsterHPBars(const UIID &)
{
    if (UI_GetInGameDlgStack().Count() > 0)
    {
        return;
    }

    Prefs::GetMutableGameplayPrefs().SetShowMonsterHPBars(!Prefs::GetGameplayPrefs().GetShowMonsterHPBars());

    UIGame::ToggledMonsterHPBars();
}

//@ 314
void UIFunction_TogglePlayerHPBars(const UIID &)
{
    if (UI_GetInGameDlgStack().Count() > 0)
    {
        return;
    }

    Prefs::GetMutableGameplayPrefs().SetShowPlayerHPBars(!Prefs::GetGameplayPrefs().GetShowPlayerHPBars());

    UIGame::ToggledPlayerHPBars();
}

//@ 328
void UIFunction_ToggleItemsOnGround(const UIID &)
{
    if (UI_GetInGameDlgStack().Count() > 0)
    {
        return;
    }

    if (Prefs::GetGameplayPrefs().GetItemsOnGroundSetting() == ITEMS_ON_GROUND_TOGGLE)
    {
        if (!gtTooltipMgr.IsShowingItemTooltipWithAltInstructions())
        {
            Prefs::GetMutableGameplayPrefs().SetShowItemsOnGround(!Prefs::GetGameplayPrefs().GetShowItemsOnGround());
            UIGame::ToggledItemsOnGround();
        }
    }
    else if (Prefs::GetGameplayPrefs().GetItemsOnGroundSetting() == ITEMS_ON_GROUND_SHOW_FOR_DURATION)
    {
        CPlayerResetShownItemsOnGroundDuration();
    }
}

