//@ 465
void UIConsoleFunction_CloseAll(const UIID & id, const int32 nControllerIndex)
{
    int32 nCurrentControllerIndex = UI_GetPrimaryUIController();
    if (nCurrentControllerIndex == nControllerIndex || nCurrentControllerIndex == -1)
    {
        if (UI_CloseAllTabs())
        {
            UIInventory::Console::OnInventoryHotkey(id, nControllerIndex);
        }
    }
}

//@ 486
void UIConsoleFunction_PauseOrJoin(const UIID & id, const int32 nControllerIndex)
{
    Player * ptPlayer = PlayerGetByControllerIndex(nControllerIndex);
    if (ptPlayer != NULL && UI_TestID(UIWND_PAUSE_CONSOLE))
    {
        if (Console::Screens::IsScreenOpen(Console::Screens::RIFT_JOIN_SCREEN_SET, 0))
        {
            UIGame::DisplayErrorString(StringListFetch("ConsoleErrors:CannotPauseWhenJoiningTieredRift"));
            return;
        }

        if (UIBossEncounter::IsActive())
        {
            UIGame::DisplayErrorString(StringListFetch("ConsoleErrors:CannotPauseWhenJoiningBossEncounter"));
            return;
        }

        if (UISetDungeon::IsActive())
        {
            UIGame::DisplayErrorString(StringListFetch("ConsoleErrors:CannotPauseWhenJoiningSetDungeon"));
            return;
        }

        if (UIEquipmentManagerDetails::IsActive())
        {
            Console::Screens::CloseAllScreenSets(FALSE);
        }

        if (!Console::Screens::IsScreenSetOpen() || UI_GetPrimaryUIController() == nControllerIndex)
        {
            UIWindow & tPauseWindow = UI_GetWindowFromID(UIWND_PAUSE_CONSOLE);
            if (tPauseWindow.IsActive())
            {
                UIPause::Console::Resume();
            }
            else
            {
                Console::Screens::OpenToScreen(Console::Screens::OPTIONS_SCREEN_SET, 0, nControllerIndex, FALSE);
            }
        }
    }
}

//@ 549
void UIConsoleFunction_RotateRActor(const UIID & id, const int32 nControllerIndex)
{
    if (UI_ValidateController(nControllerIndex))
    {
        UIUtils::Console::HandleUIRactorRotation(id, Console::ControllerUtils::GetRStickPosition(nControllerIndex));
    }
}

//@ 566
void UIConsoleFunction_ScreenLeft(const UIID & id, const int32 nControllerIndex)
{
    if (Console::Screens::IsScreenSetOpen())
    {
        Console::Screens::OpenPreviousScreen(nControllerIndex, FALSE);
    }
}

//@ 584
void UIConsoleFunction_ScreenRight(const UIID & id, const int32 nControllerIndex)
{
    if (Console::Screens::IsScreenSetOpen())
    {
        Console::Screens::OpenNextScreen(nControllerIndex, FALSE);
    }
}

