//@ 3113
static void * sFunction_Lookup(LPCSTR szFunction)
{
    uint32 uFuncHash = XHashKey<LPCSTR>(szFunction);

    UIFunctionMap & tMap = UI_GetUIFunctionMap();

    int32 nIdx;
    if (tMap.Lookup(uFuncHash, nIdx))
    {
        return sgtUIFunctions[nIdx].pfnFunction;
    }

    return NULL;
}

