//@ 3356
void UIFunction_InitializeMap()
{
    UIFunctionMap & tMap = UI_GetUIFunctionMap();
    for (int32 i = 0; i < sizeof(sgtUIFunctions) / sizeof(sgtUIFunctions[0]); i++)
    {
        const UIFunctionTable & tEntry = sgtUIFunctions[i];
        if (tEntry.szFunction != NULL)
        {
            BOOL bFound;
            int32 nExistingIdx;
            bFound = tMap.Lookup(tEntry.uFuncHash, nExistingIdx);
            if (bFound)
            {
                DisplayInternalError(NULL, "", 3372, ERROR_INTERNAL_FATAL); ExitProgram(ERROR_INTERNAL_FATAL);
            }

            tMap.SetAt_Tracked(tEntry.uFuncHash, i);
        }
    }
}

