//@ 603
static void sUpdateZoom()
{
    if (CWorldIsRetro())
        return;
    UIGlobals *& ptUIGlobals = CGameGet().ptUIGlobals; // line 613
    float flZoom = 0.0f; // line 616
    if ((ptUIGlobals->fConvPageZoomed || ptUIGlobals->fInvPageZoomed || ptUIGlobals->fManualZoomed) && CinematographyGetFocus() == RACTORID_INVALID)
        flZoom = 0.5f;
    CinematographySetZoom(flZoom, 1.0f);
    CinematographyUpdate(1.0f / 60.0f, TRUE);
}

