//@ 3247
void UI_UpdateRActorForInventory(
    RActor * ptRActor,
    VisualInventory & tVisualInventory,
    const SNO snoIrradianceTex,
    const VisualInventoryType eVIT,
    const PlayerClass ePlayerClass,
    const BOOL fFemale,
    const uint32 dwAnimTag,
    BOOL bDisableBlending)
{
    if (GameIsParamFlagSet(GPF_LIMIT_WEAPON_EFFECTS))
        tVisualInventory.tEquipmentCurrent.LimitEffects();
    tVisualInventory.tEquipmentCurrent.FixOffHandWeapons();
    UIRActor::PlayAnimForEquipment(ptRActor, tVisualInventory.tEquipmentCurrent, ePlayerClass, dwAnimTag, bDisableBlending);
    RActorUpdateBones(ptRActor, 1.0f / 60.0f, NULL, TRUE);
    VisualInventoryApply(ptRActor, tVisualInventory, eVIT, ePlayerClass, fFemale);
    blz::list<RActorID, blz::allocator<RActorID> > listRActors; // line 3273
    listRActors.push_back(ptRActor->id);
    while (!listRActors.empty()) {
        RActorID idRActor = listRActors.front(); // line 3277
        if (RActor * ptClothRActor = RActorTryToGet(idRActor)) { // line 3278
            RActorSettleCloth(ptClothRActor);
            RActorSetIrradianceMap(ptClothRActor, snoIrradianceTex);
            POS pos = ptClothRActor->tAttachmentList.GetHeadPosition(); // line 3282
            while (pos) {
                AttachmentID idAttachment = ptClothRActor->tAttachmentList.GetNext(pos); // line 3285
                Attachment * ptAttachment = AttachmentTryToGet(idAttachment); // line 3286
                if (ptAttachment) {
                    if (ptAttachment->snoname.snoGroup == ACTOR_SNO) {
                        listRActors.push_back((RActorID)ptAttachment->idAttachedObject);
                    } else if (ptAttachment->snoname.snoGroup == PARTICLE_SNO) {
                        ParticleSystem * ptParticles = ParticleSystemTryToGet(ptAttachment->idAttachedObject); // line 3297
                        // Original tests particle system type 1 or 3; headers expose only the int32 typedef.
                        if (ptParticles && (ptParticles->eType == 1 || ptParticles->eType == 3)) {
                            POS partPos = ptParticles->tParticleRActorList.GetHeadPosition(); // line 3300
                            while (partPos)
                                listRActors.push_back((RActorID)ptParticles->tParticleRActorList.GetNext(partPos));
                        }
                    }
                }
            }
        }
        listRActors.pop_front();
    }
    RActorSetIrradianceMap(ptRActor, snoIrradianceTex);
}

//@ 3324
RActorID UI_CreateHeroUIRActor(
    const SNO snoActor,
    const SNO snoIrradianceTex,
    const VisualEquipment & tVisualEquipment,
    const VisualInventoryType eVIT,
    const PlayerClass ePlayerClass,
    const BOOL fFemale,
    const PRTransform & transform,
    const RenderContext eContext,
    const uint32 dwAnimTag,
    const float flScale,
    BOOL bDisableBlending)
{
    RActorID idRActor = RActorCreate(snoActor, flScale, -1.0f, transform, 0, eContext, SSCENEID_INVALID); // line 3337
    if (idRActor == RACTORID_INVALID)
        return RACTORID_INVALID;
    RActor * ptRActor = RActorGet(idRActor); // line 3343
    VisualInventory tVisualInventory; // line 3345
    tVisualInventory.Init();
    tVisualInventory.tEquipmentCurrent = tVisualEquipment;
    UI_UpdateRActorForInventory(ptRActor, tVisualInventory, snoIrradianceTex, eVIT, ePlayerClass, fFemale, dwAnimTag, bDisableBlending);
    return idRActor;
}
